VER_START = '    ai = get_ai_service()\n    result = await ai.match_documents(id_bytes'
VER_END = '\n\n\n@router.get("/{listing_id}/status")'
VER_NEW = '    ai = get_ai_service()\n    try:\n        result = await asyncio.wait_for(\n            ai.match_documents(id_bytes, own_bytes, listing.category.value),\n            timeout=MATCH_TIMEOUT_SECONDS,\n        )\n    except asyncio.TimeoutError:\n        raise HTTPException(503, "خدمة التحقق مشغولة حالياً، حاول مرة أخرى بعد قليل")\n\n    score = float(result.get("match_score", 0.0))\n    ai_available = not result.get("needs_manual_review")\n    passed = bool(result.get("passed", False)) and ai_available\n\n    verification = (await db.execute(\n        select(ListingVerification).where(ListingVerification.listing_id == listing_id)\n    )).scalar_one_or_none()\n    if not verification:\n        verification = ListingVerification(id=str(uuid.uuid4()), listing_id=listing_id)\n        db.add(verification)\n\n    details = dict(result)\n    details["ai_available"] = ai_available\n    details["ai_passed"] = passed\n    verification.owner_id_doc_url = id_url\n    verification.ownership_doc_url = own_url\n    verification.match_score = score\n    verification.match_details = details\n    verification.verified_at = None\n    verification.reviewed_by = None\n    verification.reviewed_at = None\n\n    if passed:\n        # قُبلت آلياً → بانتظار تأكيد المشرف (لا قبول نهائي بدونه)\n        verification.match_status = DocMatchStatus.pending\n        verification.rejection_reason = None\n        message = "تم قبول وثائقك مبدئياً وهي بانتظار تأكيد المشرف"\n    elif not ai_available:\n        # الفحص الآلي غير متاح: تُحوَّل للمشرف صراحةً بدل القبول أو الرفض الأعمى\n        verification.match_status = DocMatchStatus.pending\n        verification.rejection_reason = None\n        message = "تعذّر الفحص الآلي للوثائق وتم تحويلها للمشرف للمراجعة اليدوية"\n    else:\n        issues = [str(i) for i in (result.get("issues") or [])]\n        unreadable = [i for i in issues if "تعذّر استخراج" in i]\n        if unreadable:\n            message = "تم رفض الوثائق: " + "؛ ".join(unreadable) + ". ارفع صوراً أوضح وبإضاءة جيدة"\n        else:\n            message = "تم رفض الوثائق: " + (\n                "؛ ".join(issues) if issues else "بيانات الهوية لا تطابق وثيقة الملكية"\n            )\n        verification.match_status = DocMatchStatus.rejected\n        verification.rejection_reason = message\n\n    listing.status = ListingStatus.docs_uploaded\n    await db.commit()\n\n    if verification.match_status == DocMatchStatus.rejected:\n        raise HTTPException(422, message)  # الواجهة تعرض detail كرسالة رفض\n\n    return {\n        "status": listing.status.value,\n        "message": message,\n        "verification": {\n            "match_status": verification.match_status.value,\n            "match_score": verification.match_score,\n            "match_details": verification.match_details,\n            "rejection_reason": verification.rejection_reason,\n            "ai_passed": passed,\n            "awaiting_admin": True,\n        },\n    }'
VER_DONE_MARK = 'details["ai_passed"] = passed'


def main():
    check_only = "--check" in sys.argv
    root = os.getcwd()
    if not (os.path.isdir(os.path.join(root, "backend", "app")) and os.path.isdir(os.path.join(root, "frontend", "src"))):
        print("خطأ: شغّل السكربت من جذر المشروع (المجلد الذي فيه backend و ai_models و frontend).")
        sys.exit(1)

    state = {}      # path -> (text_lf, crlf, original_bytes)
    def load(rel):
        if rel not in state:
            p = os.path.join(root, *rel.split("/"))
            raw = open(p, "rb").read().decode("utf-8")
            state[rel] = [raw.replace("\r\n", "\n"), "\r\n" in raw, raw]
        return state[rel]

    problems, report = [], []
    for n, e in enumerate(EDITS, 1):
        try:
            st = load(e["file"])
        except FileNotFoundError:
            problems.append(f"{e['label']}: الملف غير موجود {e['file']}"); continue
        t = st[0]
        if e["new"] in t:
            report.append(("مطبّق مسبقاً", e)); continue
        c = t.count(e["find"])
        if c != 1:
            problems.append(f"{e['label']} في {e['file']}: وجدت الموضع {c} مرة (المطلوب مرة واحدة) — الملف يختلف عن نسختي")
            continue
        st[0] = t.replace(e["find"], e["new"]); report.append(("سيُطبَّق", e))

    # إعادة كتابة نهاية upload_documents
    vrel = "backend/app/api/routes/verification.py"
    try:
        vs = load(vrel)
        if VER_DONE_MARK in vs[0]:
            report.append(("مطبّق مسبقاً", {"label": "V4 upload_documents", "file": vrel}))
        else:
            a, b = vs[0].find(VER_START), vs[0].find(VER_END)
            if a < 0 or b < 0 or vs[0].count(VER_START) != 1:
                problems.append(f"V4 في {vrel}: لم أجد بداية/نهاية دالة upload_documents")
            else:
                vs[0] = vs[0][:a] + VER_NEW + vs[0][b:]
                report.append(("سيُطبَّق", {"label": "V4 upload_documents", "file": vrel}))
    except FileNotFoundError:
        problems.append(f"V4: الملف غير موجود {vrel}")

    iq_rel = "backend/app/services/image_quality.py"
    iq_path = os.path.join(root, *iq_rel.split("/"))
    iq_exists = os.path.isfile(iq_path)

    for status, e in report:
        print(f"{status:12} {e['label']:42} {e['file']}")
    print("إنشاء ملف جديد:" if not iq_exists else "موجود مسبقاً:", iq_rel)

    if problems:
        print("\n!! لم يُكتب أي ملف. المشاكل:")
        for p in problems: print("   -", p)
        print("أرسل لي هذا الإخراج كاملاً.")
        sys.exit(2)

    if check_only:
        print("\nالفحص ناجح: كل التعديلات قابلة للتطبيق أو مطبّقة مسبقاً.")
        return

    changed = []
    for rel, (text, crlf, raw) in state.items():
        out = text.replace("\n", "\r\n") if crlf else text
        if out != raw:
            p = os.path.join(root, *rel.split("/"))
            if not os.path.exists(p + ".bak"):
                shutil.copyfile(p, p + ".bak")
            open(p, "wb").write(out.encode("utf-8"))
            changed.append(rel)
    if not iq_exists:
        open(iq_path, "wb").write(IMAGE_QUALITY_PY.encode("utf-8")); changed.append(iq_rel)
    print("\nتم. الملفات المعدّلة/المنشأة:")
    for c in changed: print("   ", c)
    if not changed: print("    (لا شيء — كل التعديلات مطبّقة مسبقاً)")


if __name__ == "__main__":
    main()
